// Package lab runs one throwaway Postgres + Inspector pair per reader.
//
// All state is in memory. On start-up the gateway removes every lab it finds
// by label, so a restart ends all labs and clears the queue.
package lab

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"errors"
	"log/slog"
	"sync"
	"time"
)

// Runner starts and stops the containers of one lab. Name is generated by
// the Manager, never taken from a request.
type Runner interface {
	// Start brings the lab up and returns the Inspector's host:port, reachable
	// from the gateway only.
	Start(ctx context.Context, name string, env []string) (addr string, err error)
	Stop(ctx context.Context, name string) error
	// StopAll removes every lab container, network and volume by label.
	StopAll(ctx context.Context) error
}

// ActionInfo is one Inspector action, as its /health lists it.
type ActionInfo struct {
	Name        string `json:"name"`
	Description string `json:"description"`
	Query       string `json:"query"`
}

// Prober asks a just-started Inspector for its action list, retrying until
// it answers or ctx ends.
type Prober func(ctx context.Context, addr string) ([]ActionInfo, error)

type State string

const (
	None     State = "none"
	Queued   State = "queued"
	Starting State = "starting"
	Ready    State = "ready"
	Failed   State = "failed"
)

var ErrTooManyStarts = errors.New("too many lab starts; try again later")
var ErrQueueFull = errors.New("the lab queue is full; try again in a few minutes")

// Status is what the browser sees. Addr and the lab's name stay server-side.
type Status struct {
	State     State        `json:"state"`
	Position  int          `json:"position,omitempty"`
	Actions   []ActionInfo `json:"actions,omitempty"`
	ExpiresAt *time.Time   `json:"expires_at,omitempty"`
}

type Config struct {
	MaxLabs  int           // labs starting or ready at once
	MaxQueue int           // readers waiting for a slot
	Idle     time.Duration // since the last action
	Lifetime time.Duration // hard cap from start
	// StartsPerHour caps how often one reader may start a lab.
	StartsPerHour int
	// QueueStale drops a queued reader who stopped polling.
	QueueStale   time.Duration
	StartTimeout time.Duration
}

type lab struct {
	name       string
	state      State
	addr       string
	actions    []ActionInfo
	started    time.Time // when it became ready
	lastActive time.Time
	cancel     context.CancelFunc
}

type Manager struct {
	cfg    Config
	runner Runner
	probe  Prober
	log    *slog.Logger
	now    func() time.Time

	mu     sync.Mutex
	labs   map[string]*lab // by reader key
	queue  []string        // reader keys, oldest first
	starts map[string][]time.Time
	wg     sync.WaitGroup
}

func NewManager(cfg Config, runner Runner, probe Prober, log *slog.Logger) *Manager {
	return &Manager{
		cfg: cfg, runner: runner, probe: probe, log: log, now: time.Now,
		labs: map[string]*lab{}, starts: map[string][]time.Time{},
	}
}

// Start gives the reader their lab: the existing one, a new one, or a queue
// slot. One lab per reader, so extra tabs share it.
func (m *Manager) Start(user string) (Status, error) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if l, ok := m.labs[user]; ok && l.state != Failed {
		l.lastActive = m.now()
		return m.statusLocked(user), nil
	}
	now := m.now()
	recent := m.starts[user][:0]
	for _, t := range m.starts[user] {
		if now.Sub(t) < time.Hour {
			recent = append(recent, t)
		}
	}
	if len(recent) >= m.cfg.StartsPerHour {
		m.starts[user] = recent
		return Status{}, ErrTooManyStarts
	}
	if m.activeLocked() >= m.cfg.MaxLabs && len(m.queue) >= m.cfg.MaxQueue {
		return Status{}, ErrQueueFull
	}
	m.starts[user] = append(recent, now)
	l := &lab{name: newName(), state: Queued, lastActive: now}
	m.labs[user] = l
	m.queue = append(m.queue, user)
	m.promoteLocked()
	return m.statusLocked(user), nil
}

// Status reports the reader's lab. Polling it keeps a queue slot alive, but
// does not count as activity for a running lab.
func (m *Manager) Status(user string) Status {
	m.mu.Lock()
	defer m.mu.Unlock()
	if l, ok := m.labs[user]; ok && l.state == Queued {
		l.lastActive = m.now()
	}
	return m.statusLocked(user)
}

// Ready returns the Inspector address and action list of the reader's lab,
// if it is ready.
func (m *Manager) Ready(user string) (addr string, actions []ActionInfo, ok bool) {
	m.mu.Lock()
	defer m.mu.Unlock()
	l, found := m.labs[user]
	if !found || l.state != Ready {
		return "", nil, false
	}
	return l.addr, l.actions, true
}

// Touch records reader activity (an action), resetting the idle timer.
func (m *Manager) Touch(user string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	if l, ok := m.labs[user]; ok {
		l.lastActive = m.now()
	}
}

// Stop ends the reader's lab or leaves the queue.
func (m *Manager) Stop(user string) {
	m.mu.Lock()
	defer m.mu.Unlock()
	m.removeLocked(user)
	m.promoteLocked()
}

// Reap ends idle and expired labs and drops stale queue entries. The caller
// runs it on a ticker.
func (m *Manager) Reap() {
	m.mu.Lock()
	defer m.mu.Unlock()
	now := m.now()
	for user, l := range m.labs {
		switch {
		case l.state == Ready && (now.Sub(l.lastActive) >= m.cfg.Idle || now.Sub(l.started) >= m.cfg.Lifetime):
			m.log.Info("lab reaped", "lab", l.name)
			m.removeLocked(user)
		case l.state == Queued && now.Sub(l.lastActive) >= m.cfg.QueueStale:
			m.removeLocked(user)
		case l.state == Failed && now.Sub(l.lastActive) >= m.cfg.QueueStale:
			delete(m.labs, user)
		}
	}
	m.promoteLocked()
}

// Run reaps every interval until ctx ends, then stops every lab.
func (m *Manager) Run(ctx context.Context, interval time.Duration) {
	t := time.NewTicker(interval)
	defer t.Stop()
	for {
		select {
		case <-ctx.Done():
			m.mu.Lock()
			for user := range m.labs {
				m.removeLocked(user)
			}
			m.mu.Unlock()
			m.wg.Wait()
			return
		case <-t.C:
			m.Reap()
		}
	}
}

func (m *Manager) activeLocked() int {
	n := 0
	for _, l := range m.labs {
		if l.state == Starting || l.state == Ready {
			n++
		}
	}
	return n
}

func (m *Manager) statusLocked(user string) Status {
	l, ok := m.labs[user]
	if !ok {
		return Status{State: None}
	}
	st := Status{State: l.state}
	switch l.state {
	case Queued:
		for i, u := range m.queue {
			if u == user {
				st.Position = i + 1
			}
		}
	case Ready:
		st.Actions = l.actions
		exp := l.lastActive.Add(m.cfg.Idle)
		if hard := l.started.Add(m.cfg.Lifetime); hard.Before(exp) {
			exp = hard
		}
		st.ExpiresAt = &exp
	}
	return st
}

// removeLocked forgets the reader's lab and tears its containers down in the
// background, so a slow `docker compose down` never holds the lock.
func (m *Manager) removeLocked(user string) {
	l, ok := m.labs[user]
	if !ok {
		return
	}
	delete(m.labs, user)
	for i, u := range m.queue {
		if u == user {
			m.queue = append(m.queue[:i], m.queue[i+1:]...)
			break
		}
	}
	if l.state == Queued {
		return // nothing was started
	}
	if l.cancel != nil {
		l.cancel()
	}
	m.wg.Add(1)
	go func() {
		defer m.wg.Done()
		ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
		defer cancel()
		if err := m.runner.Stop(ctx, l.name); err != nil {
			m.log.Error("lab stop failed", "lab", l.name, "err", err)
		}
	}()
}

func (m *Manager) promoteLocked() {
	for len(m.queue) > 0 && m.activeLocked() < m.cfg.MaxLabs {
		user := m.queue[0]
		m.queue = m.queue[1:]
		l := m.labs[user]
		l.state = Starting
		ctx, cancel := context.WithTimeout(context.Background(), m.cfg.StartTimeout)
		l.cancel = cancel
		m.wg.Add(1)
		go m.launch(ctx, user, l)
	}
}

func (m *Manager) launch(ctx context.Context, user string, l *lab) {
	defer m.wg.Done()
	env := []string{
		"GLASSHOUSE_PG_ADMIN_PASSWORD=" + randomHex(16),
		"GLASSHOUSE_PG_INSPECTOR_PASSWORD=" + randomHex(16),
	}
	addr, err := m.runner.Start(ctx, l.name, env)
	var actions []ActionInfo
	if err == nil {
		actions, err = m.probe(ctx, addr)
	}

	m.mu.Lock()
	defer m.mu.Unlock()
	if m.labs[user] != l {
		return // stopped while starting; removeLocked already tears it down
	}
	if err != nil {
		m.log.Error("lab start failed", "lab", l.name, "err", err)
		l.state = Failed
		l.lastActive = m.now()
		m.wg.Add(1)
		go func() {
			defer m.wg.Done()
			stopCtx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
			defer cancel()
			_ = m.runner.Stop(stopCtx, l.name)
		}()
		m.promoteLocked()
		return
	}
	now := m.now()
	l.state, l.addr, l.actions, l.started, l.lastActive = Ready, addr, actions, now, now
	m.log.Info("lab ready", "lab", l.name)
}

func newName() string { return "lab-" + randomHex(6) }

func randomHex(n int) string {
	b := make([]byte, n)
	if _, err := rand.Read(b); err != nil {
		panic(err) // crypto/rand never fails on supported platforms
	}
	return hex.EncodeToString(b)
}
